var t=`0223-arroz-de-marisco`;var n=`world-0223`;var o=`PT`;var r=`southern-europe`;var s=4;var a=40;var l={en:`Arroz de Marisco`,ua:`Рис із морепродуктами`};var d={en:`A traditional Portugal dish made with yellow onion, garlic, tomato, white rice. This home-style preparation follows its characteristic cooking method and uses measured ingredients.`,ua:`Традиційна страва кухні країни Португалія. Основні інгредієнти: жовта цибуля, часник, помідор, білий рис. Домашній варіант із характерною технологією та поетапно розподіленими продуктами.`};var g=[{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 9 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 9 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:9,i:[[`yellow-onion`,160,`g`],[`garlic`,4,`clove`],[`extra-virgin-olive-oil`,60,`ml`],[`tomato`,250,`g`]]},{en:`Spread the rice evenly into the flavorful liquid. Cook uncovered or partly covered for about 20 minutes until the liquid is absorbed; do not over-stir.`,ua:`Рівномірно розподіліть рис у ароматній рідині. Готуйте приблизно 20 хвилин до вбирання рідини, не перемішуючи надмірно.`,t:[`rice-washing`,`absorption-cooking`],m:20,i:[[`white-rice`,330,`g`],[`fish-stock`,1e3,`ml`],[`dry-white-wine`,120,`ml`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 9 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 9 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:9,i:[[`shrimp`,250,`g`],[`mussel`,400,`g`],[`clam`,350,`g`],[`squid`,200,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`parsley`,20,`g`],[`lemon-juice`,20,`ml`]]}];var u={slug:t,id:n,country:`PT`,region:r,servings:4,minutes:40,title:l,text:d,steps:g};export{o as country,u as default,n as id,a as minutes,r as region,s as servings,t as slug,g as steps,d as text,l as title};